let resumeAvatarChoice=false;
document.addEventListener('boyi:nickname-required',()=>{resumeAvatarChoice=false;$('#room-nickname').value='';requestAnimationFrame(()=>$('#room-nickname').focus({preventScroll:true}));});
$('#nickname-form').onsubmit=async event=>{event.preventDefault();const button=$('#nickname-save'),entering=!social?.getStats().joined;button.disabled=true;$('#nickname-status').textContent='';try{const ok=await social?.changeNickname($('#room-nickname').value);if(!ok){$('#nickname-status').textContent='昵称暂未保存，请检查输入或连接后重试';return;}if(entering){resumeAvatarChoice=false;social.showAvatarChoices?.();}else{closePanel();if(resumeAvatarChoice){resumeAvatarChoice=false;$('#choose-avatar').click();}}notify(entering?'昵称已设置，选择本次小屋形象':'昵称已更新');}catch{$('#nickname-status').textContent='昵称暂未保存，请重试';}finally{button.disabled=false;}};
$('#save-room-name').onclick=async()=>{const button=$('#save-room-name');button.disabled=true;try{const ok=await social?.changeNickname($('#visitor-name').value);notify(ok?'昵称已更新':'请输入 1–18 字的昵称');}catch{notify('昵称暂未保存，请重试');}finally{button.disabled=false;}};
if(directEntry)enterScene();
